package com.ditsjohann.warfront.registry;

import com.ditsjohann.warfront.Warfront;
import net.minecraft.sounds.SoundEvent;
import net.minecraftforge.registries.DeferredRegister;
import net.minecraftforge.registries.ForgeRegistries;
import net.minecraftforge.registries.RegistryObject;

import java.util.HashMap;
import java.util.Map;

/** All WARFRONT sounds (procedurally generated by tools/gen_sounds.py). */
public final class ModSounds {
    public static final DeferredRegister<SoundEvent> REGISTER = DeferredRegister.create(ForgeRegistries.SOUND_EVENTS, Warfront.MODID);
    private static final Map<String, RegistryObject<SoundEvent>> BY_NAME = new HashMap<>();

    public static final String[] NAMES = {
            "rifle_shot", "rifle_shot_far", "carbine_shot", "carbine_shot_far", "lmg_shot", "lmg_shot_far",
            "sniper_shot", "sniper_shot_far", "pistol_shot", "pistol_shot_far", "shotgun_shot", "shotgun_shot_far",
            "suppressed_shot", "reload_mag_out", "reload_mag_in", "reload_bolt", "dry_fire", "fire_mode",
            "grenade_pin", "c4_beep", "repair_loop", "defib", "bag_drop", "resupply",
            "hitmarker", "headshot", "kill_confirm", "bullet_crack", "bullet_impact", "ricochet", "glass_shatter",
            "score_ping", "flag_captured", "flag_lost", "capture_tick", "ticket_warning", "deploy", "spot",
            "victory", "defeat", "explosion", "explosion_far", "grenade_explode", "tank_cannon", "rocket_launch",
            "rocket_loop", "tower_alarm", "tower_collapse", "tank_engine", "turret_traverse", "vehicle_hit", "vehicle_warning", "ammo_low", "casing", "breath_in", "breath_out"
    };

    static {
        for (String n : NAMES) {
            BY_NAME.put(n, REGISTER.register(n, () -> SoundEvent.createVariableRangeEvent(Warfront.id(n))));
        }
    }

    public static SoundEvent get(String name) {
        RegistryObject<SoundEvent> ro = BY_NAME.get(name);
        if (ro == null) throw new IllegalArgumentException("Unknown WARFRONT sound " + name);
        return ro.get();
    }

    public static boolean exists(String name) { return BY_NAME.containsKey(name); }

    private ModSounds() {}
}
